"""Tests for statement parsers."""

import pytest
from pathlib import Path
from backend.ingest.parsers import parse_statement, detect_format, ParseError

# Use sample data generated by generate_data.py
SAMPLE_DATA_DIR = Path(__file__).parent.parent.parent.parent / "sample_data" / "case_001"

def test_detect_csv_format():
    """Test CSV format detection."""
    csv_file = list(SAMPLE_DATA_DIR.glob("*.csv"))[0]
    format_type = detect_format(csv_file)
    assert format_type in ["sbi_csv", "hdfc_csv", "generic_csv"]

def test_detect_excel_format():
    """Test Excel format detection."""
    excel_files = list(SAMPLE_DATA_DIR.glob("*.xlsx"))
    if excel_files:
        format_type = detect_format(excel_files[0])
        assert format_type in ["hdfc_excel", "generic_excel"]

def test_detect_pdf_format():
    """Test PDF format detection."""
    pdf_files = list(SAMPLE_DATA_DIR.glob("*.pdf"))
    if pdf_files:
        format_type = detect_format(pdf_files[0])
        assert format_type in ["icici_pdf", "sbi_pdf", "generic_pdf"]

def test_parse_csv_statement():
    """Test parsing CSV statement."""
    csv_file = list(SAMPLE_DATA_DIR.glob("*.csv"))[0]
    transactions = parse_statement(csv_file)

    assert len(transactions) > 0
    # Check required fields
    for txn in transactions:
        assert "timestamp" in txn
        assert "txn_id" in txn
        assert "amount" in txn
        assert "direction" in txn
        assert "bank" in txn

def test_parse_excel_statement():
    """Test parsing Excel statement."""
    excel_files = list(SAMPLE_DATA_DIR.glob("*.xlsx"))
    if not excel_files:
        pytest.skip("No Excel file in sample data")

    transactions = parse_statement(excel_files[0])
    assert len(transactions) > 0

    for txn in transactions:
        assert "timestamp" in txn
        assert "amount" in txn
        assert txn["amount"] > 0

def test_parse_pdf_statement():
    """Test parsing PDF statement."""
    pdf_files = list(SAMPLE_DATA_DIR.glob("*.pdf"))
    if not pdf_files:
        pytest.skip("No PDF file in sample data")

    transactions = parse_statement(pdf_files[0])
    # PDF parsing is harder, may extract fewer transactions
    assert len(transactions) >= 0

def test_parse_nonexistent_file():
    """Test error handling for missing file."""
    with pytest.raises(ParseError):
        parse_statement(Path("/nonexistent/file.csv"))

def test_parse_all_case_files():
    """Integration test: parse all files in case_001."""
    all_files = list(SAMPLE_DATA_DIR.glob("*.csv")) + \
                list(SAMPLE_DATA_DIR.glob("*.xlsx")) + \
                list(SAMPLE_DATA_DIR.glob("*.pdf"))

    total_transactions = 0
    for file in all_files:
        try:
            transactions = parse_statement(file)
            total_transactions += len(transactions)
            print(f"Parsed {file.name}: {len(transactions)} transactions")
        except ParseError as e:
            print(f"Failed to parse {file.name}: {e}")

    print(f"Total transactions parsed: {total_transactions}")
    assert total_transactions > 0
